const input =
  $input.first()?.json ?? {};

const body =
  input.body &&
  typeof input.body === 'object'
    ? input.body
    : input;

const clean = value =>
  String(value ?? '').trim();

const action =
  clean(
    body.action
  ).toLowerCase();

const opportunityKey =
  clean(
    body.opportunity_key
  );

let followUpDraft =
  clean(
    body.follow_up_draft
  );

const blockingReasons = [];


/*
 * Authentication is handled directly by
 * the Webhook node using Header Auth.
 */
if (
  ![
    'save_follow_up_draft',
    'approve_and_send_follow_up',
  ].includes(action)
) {
  blockingReasons.push(
    'Unsupported follow-up action.'
  );
}


if (!opportunityKey) {
  blockingReasons.push(
    'A specific opportunity_key is required.'
  );
}


followUpDraft =
  followUpDraft
    .replace(
      /^subject:\s*[^\r\n]+(?:\r?\n)+/i,
      ''
    )
    .trim();


if (!followUpDraft) {
  blockingReasons.push(
    'The follow-up draft is empty.'
  );
}


if (followUpDraft.length > 5000) {
  blockingReasons.push(
    'The follow-up draft is too long.'
  );
}


const requestValid =
  blockingReasons.length === 0;


return [
  {
    json: {
      request_valid:
        requestValid,

      success:
        requestValid,

      http_status:
        requestValid
          ? 200
          : 400,

      message:
        requestValid
          ? 'Follow-up request validated.'
          : 'The follow-up request is invalid.',

      blocking_reasons:
        blockingReasons,

      action,

      opportunity_key:
        opportunityKey,

      follow_up_draft:
        followUpDraft,

      request_checked_at:
        new Date().toISOString(),
    },
  },
];

const request =
  $('Validate Follow-up Request')
    .first()
    .json ?? {};

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const rows =
  $input
    .all()
    .map(item => item.json ?? {})
    .filter(
      row => clean(row.opportunity_key)
    );

const requestedKey =
  clean(request.opportunity_key);

const row =
  rows.find(
    candidate =>
      clean(
        candidate.opportunity_key
      ) === requestedKey
  ) ?? null;


function blocked(
  message,
  reasons = [],
  status = 409,
) {
  return [
    {
      json: {
        can_update: false,
        success: false,
        http_status: status,

        action:
          request.action,

        opportunity_key:
          requestedKey,

        message,

        blocking_reasons:
          reasons,
      },
    },
  ];
}


if (!row) {
  return blocked(
    'The requested campaign was not found.',
    [
      'No matching Application_Tracker row exists.',
    ],
    404,
  );
}


if (
  requestedKey.startsWith('test::')
) {
  return blocked(
    'Test campaigns cannot use the production follow-up API.'
  );
}


const outreachStatus =
  upper(row.outreach_status);

const responseStatus =
  upper(row.response_status) ||
  'NO_RESPONSE';

const followUpStatus =
  upper(row.follow_up_status) ||
  'NOT_STARTED';

const followUpDate =
  clean(row.follow_up_date)
    .slice(0, 10);

const sentAt =
  clean(row.sent_at);

const replyDetectedAt =
  clean(row.reply_detected_at);

const followUpSentAt =
  clean(row.follow_up_sent_at);

const gmailMessageId =
  clean(row.gmail_message_id);

const existingThreadId =
  clean(row.gmail_thread_id);

const today =
  new Date()
    .toISOString()
    .slice(0, 10);

const shouldSend =
  request.action ===
  'approve_and_send_follow_up';

const problems = [];


if (
  outreachStatus !== 'SENT'
) {
  problems.push(
    `Outreach status is ${
      outreachStatus || 'EMPTY'
    }; expected SENT.`
  );
}


if (!sentAt) {
  problems.push(
    'The original outreach sent timestamp is missing.'
  );
}


if (
  responseStatus !== 'NO_RESPONSE' ||
  replyDetectedAt
) {
  problems.push(
    'A reply has already been detected for this campaign.'
  );
}


if (
  followUpSentAt ||
  followUpStatus === 'SENT'
) {
  problems.push(
    'A follow-up was already sent.'
  );
}


if (!followUpDate) {
  problems.push(
    'The follow-up date is missing.'
  );
}


if (
  shouldSend &&
  followUpDate &&
  followUpDate > today
) {
  problems.push(
    `The follow-up is scheduled for ${followUpDate} and is not due yet.`
  );
}


if (
  shouldSend &&
  followUpStatus !== 'DRAFT_READY'
) {
  problems.push(
    `Follow-up status is ${
      followUpStatus || 'EMPTY'
    }; expected DRAFT_READY.`
  );
}


if (
  shouldSend &&
  !gmailMessageId
) {
  problems.push(
    'The original Gmail message ID is missing.'
  );
}


if (
  shouldSend &&
  !existingThreadId
) {
  problems.push(
    'The original Gmail thread ID is missing.'
  );
}


if (problems.length) {
  return blocked(
    'The follow-up action is currently blocked.',
    problems,
  );
}


const now =
  new Date().toISOString();


return [
  {
    json: {
      ...row,

      can_update:
        true,

      success:
        true,

      http_status:
        200,

      action:
        request.action,

      opportunity_key:
        requestedKey,

      follow_up_draft:
        clean(
          request.follow_up_draft
        ),

      follow_up_status:
        shouldSend
          ? 'SENDING'
          : 'DRAFT_READY',

      follow_up_approval:
        shouldSend
          ? 'APPROVED'
          : 'PENDING',

      follow_up_approved_at:
        shouldSend
          ? now
          : clean(
              row.follow_up_approved_at
            ),

      should_send:
        shouldSend,

      gmail_message_id:
        gmailMessageId,

      gmail_thread_id:
        existingThreadId,

      last_updated:
        now,
    },
  },
];

const prepared =
  $('Prepare Follow-up Update')
    .first()
    ?.json ?? {};

return [
  {
    json: {
      ...prepared,
    },
  },
];

const prepared =
  $('Prepare Follow-up Update')
    .first()
    ?.json ?? {};

const gmail =
  $('Reply in Gmail Thread')
    .first()
    ?.json ?? {};

const clean = value =>
  String(value ?? '').trim();

const now =
  new Date().toISOString();


return [
  {
    json: {
      ...prepared,

      follow_up_status:
        'SENT',

      follow_up_approval:
        'APPROVED',

      follow_up_approved_at:
        clean(
          prepared
            .follow_up_approved_at
        ) || now,

      follow_up_sent_at:
        now,

      follow_up_message_id:
        clean(
          gmail.id ??
          gmail.messageId
        ),

      response_status:
        'NO_RESPONSE',

      last_updated:
        now,
    },
  },
];

const prepared =
  $('Prepare Follow-up Update')
    .first()
    ?.json ?? {};

const clean = value =>
  String(value ?? '').trim();


return [
  {
    json: {
      success:
        true,

      http_status:
        200,

      action:
        clean(prepared.action),

      opportunity_key:
        clean(
          prepared.opportunity_key
        ),

      follow_up_status:
        'DRAFT_READY',

      follow_up_approval:
        'PENDING',

      should_send:
        false,

      message:
        'Follow-up draft saved successfully.',

      updated_at:
        clean(
          prepared.last_updated
        ) ||
        new Date().toISOString(),
    },
  },
];

const sent =
  $('Prepare Follow-up Sent Update')
    .first()
    ?.json ?? {};

const clean = value =>
  String(value ?? '').trim();


return [
  {
    json: {
      success:
        true,

      http_status:
        200,

      action:
        'approve_and_send_follow_up',

      opportunity_key:
        clean(
          sent.opportunity_key
        ),

      follow_up_status:
        'SENT',

      follow_up_approval:
        'APPROVED',

      follow_up_sent_at:
        clean(
          sent.follow_up_sent_at
        ),

      follow_up_message_id:
        clean(
          sent.follow_up_message_id
        ),

      gmail_thread_id:
        clean(
          sent.gmail_thread_id
        ),

      message:
        'Follow-up sent successfully in the existing Gmail thread.',
    },
  },
];
